def redirected(mem):
    return [r for r in mem.get('_records', []) if r['decision'] == 'boss_pursuit_redirected']


def test_a_southern_reading_still_redirects_and_logs_the_distance(monkeypatch):
    arm(monkeypatch)
    mem = memory((778, 637), read_tick=4990)
    assert bp.step(picker(), mem, FakeFrame()) == [bp.pad('a')]
    assert mem['boss_pursuit']['outcome'] == 'redirected'
    metric = redirected(mem)[0]['observed_metric']
    assert metric['boss_cell'] == [778, 637]
    assert metric['boss_cell_age'] == 10
    assert metric['unit_cell'] == [570, 215]
    assert metric['distance'] == [208, 422]
    assert metric['target_cell'] == [136, 118]


def test_the_unit_cell_is_read_when_the_picker_first_opens(monkeypatch):
    arm(monkeypatch, roof=False)
